CREATE SCHEMA IF NOT EXISTS {{ DATABASE }}.APP;

create or replace view {{ DATABASE }}.APP.CUSTOMER_ORDERS(
	CUSTOMER_ID,
	FULL_NAME,
	ORDER_ID,
	AMOUNT,
	ORDER_TS
) as
SELECT c.CUSTOMER_ID, c.FULL_NAME, o.ORDER_ID, o.AMOUNT, o.ORDER_TS
FROM APP.CUSTOMERS c
JOIN APP.ORDERS o ON o.CUSTOMER_ID = c.CUSTOMER_ID;

