create or replace view {{ DATABASE }}.APP.CUSTOMER_ORDER_DETAILS(
	CUSTOMER_ID,
	FULL_NAME,
	EMAIL,
	ORDER_ID,
	ORDER_TS,
	ORDER_TOTAL_AMOUNT,
	ITEM_ID,
	PRODUCT_NAME,
	QUANTITY,
	UNIT_PRICE,
	LINE_ITEM_TOTAL
) as
SELECT
  c.CUSTOMER_ID,
  c.FULL_NAME,
  c.EMAIL,
  o.ORDER_ID,
  o.ORDER_TS,
  o.AMOUNT                              AS ORDER_TOTAL_AMOUNT,
  oi.ITEM_ID,
  oi.PRODUCT_NAME,
  oi.QUANTITY,
  oi.UNIT_PRICE,
  (oi.QUANTITY * oi.UNIT_PRICE)         AS LINE_ITEM_TOTAL
FROM {{ DATABASE }}.APP.CUSTOMERS c
LEFT JOIN {{ DATABASE }}.APP.ORDERS o
  ON c.CUSTOMER_ID = o.CUSTOMER_ID
LEFT JOIN {{ DATABASE }}.APP.ORDER_ITEMS oi
  ON o.ORDER_ID = oi.ORDER_ID;

